import random
import time


def with_retry(fn, *, attempts: int = 5, base: float = 0.5,
              cap: float = 30.0, retry_on=(ConnectionError, TimeoutError)):
    """Exponential backoff with full jitter.

    Full jitter (random between 0 and the ceiling) rather than a fixed delay,
    because N clients that fail together and retry on the same schedule
    synchronise into a thundering herd and fail together again.
    """
    for attempt in range(attempts):
        try:
            return fn()
        except retry_on:
            if attempt == attempts - 1:
                raise
            ceiling = min(cap, base * 2 ** attempt)
            time.sleep(random.uniform(0, ceiling))

